By a proper ordering of vertices in $G_{n_1}^C \triangleright (G_{n_2}^V\cup G_{n_3}^E)$, the distance matrix $D(G_{n_1}^C \triangleright (G_{n_2}^V\cup G_{n_3}^E))$ can be written as\\

 $\begin{aligned}
 &D(G_{n_1}^C \triangleright (G_{n_2}^V\cup G_{n_3}^E))\\
 &= \scriptsize{\begin{bmatrix} J_{n_1}-I_{n_1}+A(G_{n_1}) & 2J_{n_1\times m_1}-Q(G_{n_1}) & J_{n_1\times n_2}& 2J_{n_1\times n_3} \\ 2J_{m_1\times n_1}-Q(G_{n_1})^T & 2(J_{m_1}-I_{m_1}) & 2J_{m_1\times n_2}& J_{m_1\times n_3}\\ J_{n_2\times n_1} & 2J_{n_2\times m_1} & 2(J_{n_2}-I_{n_2})-A(G_{n_2})& 3J_{n_2\times n_3}\\2J_{n_3\times n_1}& J_{n_3\times m_1}& 3J_{n_3\times n_2}& 2(J_{n_3}-I_{n_3})-A(G_{n_3}) \end{bmatrix}}.
 \end{aligned}$\\
 \\
  Let $k_i=\theta_{i1}\geq \theta_{i2}\geq\dots\geq \theta_{in_i}$ be the $A$-eigenvalues of $G_{n_i}$, where $i = 1, 2, 3.$ Let $U$ be a vector such that $A(G_{n_1})U= \theta_{1j}U$ (for $j= 2, 3,\ldots, n_1$), then by Perron-Frobenius theory $J_{1\times n_{1}}U= 0$.\\
 Now let, $\phi_1= \begin{bmatrix} tU\\Q(G_{n_1})^TU\\0\\0\end{bmatrix}$ be an eigenvector of $D(G_{n_1}^C \triangleright (G_{n_2}^V\cup G_{n_3}^E))$ for the eigenvalue $\mu$, where $t$ is a real number. Then $D(G_{n_1}^C \triangleright (G_{n_2}^V\cup G_{n_3}^E))\phi_1= \mu \phi_1$.\\
 That is,
 \\
\begin{equation*}
      \scriptsize{\begin{aligned}
     &\begin{bmatrix}J_{n_1}-I_{n_1}+A(G_{n_1}) & 2J_{n_1\times m_1}-Q(G_{n_1}) & J_{n_1\times n_2}& 2J_{n_1\times n_3} \\ 2J_{m_1\times n_1}-Q(G_{n_1})^T & 2(J_{m_1}-I_{m_1}) & 2J_{m_1\times n_2}& J_{m_1\times n_3}\\ J_{n_2\times n_1} & 2J_{n_2\times m_1} & 2(J_{n_2}-I_{n_2})-A(G_{n_2})& 3J_{n_2\times n_3}\\2J_{n_3\times n_1}& J_{n_3\times m_1}& 3J_{n_3\times n_2}& 2(J_{n_3}-I_{n_3})-A(G_{n_3}) \end{bmatrix}\begin{bmatrix} tU\\Q(G_{n_1})^TU\\0\\0\end{bmatrix}\\
     &= \mu\begin{bmatrix} tU\\Q(G_{n_1})^TU\\0\\0\end{bmatrix}\\
     \\
     &\begin{bmatrix}(-t+\theta_{1j}t-\theta_{1j}-k_1)U\\(-t-2)Q(G_{n_1})^TU\\0\\0\end{bmatrix}= \begin{bmatrix} \mu tU\\\mu Q(G_{n_1})^TU\\0\\0\end{bmatrix}.
     \end{aligned}}
 \end{equation*}

Therefore,
 \begin{equation*}
\begin{aligned}
\quad -t+\theta_{1j}t-\theta_{1j}-k_1&= \mu t\\
 \quad-t-2&= \mu
	\end{aligned}
\end{equation*}
from this, we get $$t^2+(\theta_{1j}+1)t-(\theta_{1j}+k_1)= 0$$
 so that $t$ has two values
\begin{equation*}
\begin{aligned}
&t_1 = \frac{-(\theta_{1j}+1)+ \sqrt{(\theta_{1j}+1)^2+4(\theta_{1j}+k_1)}}{2},\\
& t_2 = \frac{-(\theta_{1j}+1)- \sqrt{(\theta_{1j}+1)^2+4(\theta_{1j}+k_1)}}{2}.
 \end{aligned}
\end{equation*}
That is,  $-t_1-2$ and $-t_2-2$ are eigenvalues of $D(G_{n_1}^C \triangleright (G_{n_2}^V\cup G_{n_3}^E))$ corresponding to the eigenvalues $\theta_{1j}\neq k_1$ of $A(G_{n_1})$. Thus, we get $2(n_1-1)$ eigenvalues of $D(G_{n_1}^C \triangleright (G_{n_2}^V\cup G_{n_3}^E))$.\\
  By Lemma $2.1$, we get $Q(G_{n_1})V=0$, where $V$ is an eigenvector of $L(G_{n_1})$ corresponding to the eigenvalue $-2$ (repeated $m_1-n_1$ times).\\ If $\phi_2= \begin{bmatrix}0\\V\\0\\0\end{bmatrix}$, then we have $$D(G_{n_1}^C \triangleright (G_{n_2}^V\cup G_{n_3}^E))\phi_2= -2\phi_2.$$ Therefore, $-2$ is an eigenvalue of $D(G_{n_1}^C \triangleright (G_{n_2}^V\cup G_{n_3}^E))$ repeated $m_1-n_1$ times.\\
 Consider the eigenvalue $\theta_{2j}$ (for $j= 2,3,\ldots,n_2)$ of $G_{n_2}$ with an eigenvector $W$ such that $J_{1\times n_2}W= 0$.\\ Put $\phi_3= \begin{bmatrix}0\\0\\W\\0 \end{bmatrix}$, then we have
  $$D(G_{n_1}^C \triangleright (G_{n_2}^V\cup G_{n_3}^E))\phi_3= -(\theta_{2j} +2)\phi_3.$$This shows that $-(\theta_{2j} +2)$ are eigenvalues of $D(G_{n_1}^C \triangleright (G_{n_2}^V\cup G_{n_3}^E))$ corresponding to the eigenvalues $\theta_{2j}\neq k_2$ of $A(G_{n_2})$.\\
  Similarly, for each eigenvalue $\theta_{3j}$ (for $j= 2,3,\ldots,n_3$) of $G_{n_3}$, we get an eigenvalue $-(\theta_{3j} +2)$ of $D(G_{n_1}^C \triangleright (G_{n_2}^V\cup G_{n_3}^E))$ with eigenvector $\begin{bmatrix}0\\0\\0\\X\end{bmatrix}.$ 
  Thus, we get $2n_1-2+m_1-n_1+n_2-1+n_3-1= n_1+m_1+n_2+n_3-4$ eigenvalues of $D(G_{n_1}^C \triangleright (G_{n_2}^V\cup G_{n_3}^E))$.
  All the other eigenvalues of $D(G_{n_1}^C \triangleright (G_{n_2}^V\cup G_{n_3}^E))$ are the eigenvalues of the equitable quotient matrix
\[M= \begin{bmatrix} n_1-1+k_1& 2m_1-k_1& n_2& 2n_3\\2n_1-2& 2m_1-2& 2n_2& n_3\\n_1& 2m_1& 2n_2-k_2-2& 3n_3\\2n_1& m_1& 3n_2& 2n_3-k_3-2\end{bmatrix}.\]

Let $k_1=\theta_1\geq\theta_2\geq\cdots\geq \theta_{n_1}$, $2=\lambda_1\geq \lambda_2\geq\cdots\geq\lambda_a$ and $k_2=\gamma_1\geq\gamma_2\geq\cdots\geq \gamma_{n_2}$ be the $A$-eigenvalues of $H_{n_1}$, $C_P$ and $H_{n_2}$ respectively. 
From Theorem $2.2$, the $D$-eigenvalues of $ H_{n_1}^C \triangleright (C_P^V\cup H_{n_2}^E)$ are $\frac{-3+\theta_j\pm \sqrt{(\theta_j+1)^2+4(\theta_j+k_1)}}{2}$, $j= 2, 3,\ldots, n_1 $; $-2$ with multiplicity $m_1-n_1$; $-\lambda_{j^{'}}-2$, $j^{'}=2,3,\ldots,a$; $-\gamma_{j^{''}}-2, j^{''}=2,3,\ldots,n_2$ and along with the eigenvalues of the equitable quotient matrix $M$ of $ H_{n_1}^C \triangleright (C_P^V\cup H_{n_2}^E)$, \[\begin{bmatrix} n_1+k_1-1& 2m_1-k_1& a& 2n_2\\ 2n_1-2& 2m_1-2& 2a& n_2\\ n_1& 2m_1& 2a-4& 3n_2\\ 2n_1& m_1& 3a& 2n_2-k_2-2\end{bmatrix}\]  for every partition $P$ of $'a'$.\\
  Since $\lambda_{j^{'}}\geq -2$, for $j^{'}=2,3,\ldots,a$, we have $-(\lambda_{j^{'}}+2)\leq 0$.
 Similarly, we get $-(\gamma_{j^{''}}+2)\leq 0, j^{''}=2,3,\ldots,n_2.$\\
 Therefore,\begin{equation*}
     \begin{aligned}
     \sum_{j^{'}=2}^{a}|{-\lambda_{j^{'}}-2}|+\sum_{j^{''}=2}^{n_2}|{-\gamma_{j^{''}}-2}|&= \sum_{j^{'}=2}^a(\lambda_{j^{'}}+2)+\sum_{j^{''}=2}^{n_2}(\gamma_{j^{''}}+2)\\
     &= -2+2(a-1)-k_2+2(n_2-1)\\
     &= 2a-k_2+2n_2-6.
     \end{aligned}
 \end{equation*}
 Hence for every partition of $'a'$, the energy remains the same.

Let the vertex set of $\mathcal{G}= G_{n_1}^{C}\vee(G_{n_2}^V\cup G_{n_2}^E)$ be\\
$V(\mathcal{G})= \{v_1, v_2, \ldots, v_{n_1}, v_{e_1}, v_{e_2}, \ldots, v_{e_{m_1}}, u_1, u_2, \ldots, u_{n_2},  w_1, w_2, \ldots, w_{n_3} \}$, where $v_1, v_2, \ldots, v_{n_1}$ are the
vertices in $G_{n_1}$, $v_{e_1}, v_{e_2}, \ldots, v_{e_{m_1}}$ are the vertices corresponding to the edges of $G_{n_1}$ in
$C(G_{n_1})$, $u_1, u_2, \ldots, u_{n_2}$ are the vertices in $G_{n_2}$, and $w_1, w_2, \ldots, w_{n_3}$ are the vertices in $G_{n_3}$. Then
\begin{equation*}
    \begin{aligned}
    Tr(v_i)&= n_1+n_2+2n_3+2m_1-1,\; i= 1, \ldots, n_1.\\
    Tr(v_{e_j})&= 2n_1+2n_2+n_3+2m_1-4,\; j= 1, \ldots, m_1.\\
    Tr(u_k)&= n_1+2n_2+3n_3+2m_1-k_2-2,\; k= 1, \ldots, n_2.\\
    Tr(w_l)&= 2n_1+3n_2+2n_3+m_1-k_3-2,\; l= 1, \ldots, n_3.
    \end{aligned}
\end{equation*}
From (8),\\
\begin{equation*}
    \begin{aligned}
    W(\mathcal{G})
    &= \frac{1}{2}\sum_{v_i\in V(\mathcal{G})}Tr(v_i)\\
    &= \frac{1}{2}(n_1^2-n_1+2(n_2^2+n_3^2+n_1n_2-n_2-n_3+m_1n_3+m_1^2)\\
    &\; \; \;+4(n_1n_3+m_1n_1+m_1n_2-m_1)-(n_2k_2+n_3k_3)+6n_2n_3).
    \end{aligned}
\end{equation*}

For $i= 1,2,3$, let $G_{n_i}$ be a graph of order $n_i$ and size $m_i$, then
 \begin{itemize}
     \item [(i)] $\xi^c(\mathcal{G})=\begin{cases} 2n_1^2+5n_1n_2+5m_1n_3-2n_1+4m_1+6m_2+6m_3, & \text{if $G_{n_1}$ is triangle-free}\\3n_1^2+6n_1n_2+6m_1n_3-3n_1+6(m_1+m_2+m_3), &\text{otherwise}\end{cases}.$
     \item[(ii)]$\xi^{ce}(\mathcal{G})= \begin{cases} \frac{1}{6}\left(3n_1^2+5(n_1n_2+m_1n_3)+6m_1+4(m_2+m_3)-3n_1\right), & \text{if $G_{n_1}$ is triangle-free}\\\frac{1}{3}\left(n_1^2+2(n_1n_2+m_1n_3)-n_1+2(m_1+m_2+m_3)\right), &\text{otherwise}\end{cases}.$
 \end{itemize}

\begin{itemize}
    \item [(i)] Let $\mathcal{G}= G_{n_1}^{C}\vee(G_{n_2}^V\cup G_{n_2}^E)$, where $G_{n_1}$ is triangle-free, then from (1) by using (9) and (10), we have\\
\begin{equation*}
    \begin{aligned}
    \xi^c(\mathcal{G})&= \sum_{v\in V(G_{n_1})}2(n_1+n_2-1)+ \sum_{v\in I(G_{n_1})}2(n_3+2)\\
    &\; \; \;+ \sum_{v\in V(G_{n_2})}3(deg_{G_{n_2}}(v)+n_1)+ \sum_{v\in V(G_{n_3})} 3(deg_{G_{n_3}}(v)+m_1)\\
    &= 2n_1^2+5n_1n_2+5m_1n_3-2n_1+4m_1+6m_2+6m_3.
    \end{aligned}
\end{equation*}
Similarly in the case when $G_{n_1}$ is not a triangle-free graph by using (9) and (10) we get,
$$\xi^c(\mathcal{G})= 3n_1^2+6n_1n_2+6m_1n_3-3n_1+6(m_1+m_2+m_3).$$
\item [(ii)] Let $G_{n_1}$ be a triangle-free graph. Then from (2), by using (9) and (10), we get\\
\begin{equation*}
    \begin{aligned}
    \xi^{ce}(\mathcal{G})&= \sum_{v\in V(G_{n_1})}\frac{n_1+n_2-1}{2}+\sum_{v\in I(G_{n_1})}\frac{n_3+2}{2}+\sum_{v\in V(G_{n_2})}\frac{deg_{G_{n_2}} +n_1}{3}\\
    &\; \; \;+\sum_{v\in V(G_{n_3})}\frac{deg_{G_{n_3}}+m_1}{3}\\
    &= \frac{1}{6}\left(3n_1^2+5(n_1n_2+m_1n_3)+6m_1+4(m_2+m_3)-3n_1\right).
    \end{aligned}
\end{equation*}
Similarly in the case when $G_{n_1}$ is not a triangle-free graph by using (9) and (10) we get,
$$\xi^{ce}(\mathcal{G})= \frac{1}{3}\left(n_1^2+2(n_1n_2+m_1n_3)-n_1+2(m_1+m_2+m_3)\right).$$
\end{itemize}

For $i= 1,2,3$, let $G_{n_i}$ be a graph of order $n_i$ and size $m_i$, then
 \begin{itemize}
     \item [(i)] $\tau(\mathcal{G})=\begin{cases} 2n_1+2m_1+3n_2+3n_3, & \text{if $G_{n_1}$ is triangle-free}\\3(n_1+n_2+n_3+m_1), &\text{otherwise}\end{cases}.$
     \item[(ii)]$aveg(\mathcal{G})= \begin{cases} \frac{2n_1+2m_1+3n_2+3n_3}{n_1+n_2+n_3+m_1}, & \text{if $G_{n_1}$ is triangle-free}\\3, &\text{otherwise}\end{cases}.$
 \end{itemize}

\begin{itemize}
    \item [(i)] Consider $\mathcal{G}= G_{n_1}^{C}\vee(G_{n_2}^V\cup G_{n_2}^E)$, when $G_{n_1}$ is triangle-free, then from (3) by using (10), we get\\
    \begin{equation*}
        \begin{aligned}
        \tau(\mathcal{G})&= 2n_1+2m_1+3n_2+3n_3.
        \end{aligned}
    \end{equation*}
    Similarly when $G_{n_1}$ is not a triangle-free graph we get\\
    \begin{equation*}
        \begin{aligned}
        \tau(\mathcal{G})&= 3(n_1+n_2+n_3+m_1).
        \end{aligned}
    \end{equation*}
    \item[(ii)] From (4), we get\\
    \begin{equation*}
        \begin{aligned}
        aveg(\mathcal{G})&= \frac{\tau(\mathcal{G})}{n_1+n_2+n_3+m_1}\\
        &= \begin{cases} \frac{2n_1+2m_1+3n_2+3n_3}{n_1+n_2+n_3+m_1}, & \text{if $G_{n_1}$ is triangle-free}\\3, &\text{otherwise}\end{cases}.
        \end{aligned}
    \end{equation*}
\end{itemize}

For $i= 1,2,3$, let $G_{n_i}$ be a graph of order $n_i$ and size $m_i$, then
\begin{itemize}
     \item [(i)] $M_1(\mathcal{G})=\begin{cases} 4n_1+4m_1+9n_2+9n_3, & \text{if $G_{n_1}$ is triangle-free}\\9(n_1+n_2+n_3+m_1), &\text{otherwise}\end{cases}.$
     \item[(ii)]$M_2(\mathcal{G})= \begin{cases}4m_1+9(m_2+m_3)+2(n_1^2-n_1)+6(n_1n_2+m_1n_3) , & \text{if $G_{n_1}$ is triangle-free}\\9\left(m_1+m_2+m_3+n_1n_2+m_1n_3+\frac{n_1^2-n_1}{2}\right), &\text{otherwise}\end{cases}.$
 \end{itemize}

\begin{itemize}
    \item [(i)] Let $\mathcal{G}= G_{n_1}^{C}\vee(G_{n_2}^V\cup G_{n_2}^E)$, where $G_{n_1}$ is triangle-free, then from (5) by using (10) we get\\
    \begin{equation*}
        \begin{aligned}
        M_1(\mathcal{G})&= \sum_{v\in V(G_{n_1})}2^2+\sum_{v\in I(G_{n_1})}2^2+\sum_{v\in V(G_{n_2})}3^2+\sum_{v\in V(G_{n_3})}3^2\\
        &= 4n_1+4m_1+9n_2+9n_3.
        \end{aligned}
    \end{equation*}
    Similarly when $G_{n_1}$ is not a triangle-free graph we get,\\
    $$M_1(\mathcal{G})= 9(n_1+n_2+n_3+m_1).$$
    \item[(ii)] Let $G_{n_1}$ be a triangle-free graph. Then from (5) by using (10) we get\\
    \begin{equation*}
        \begin{aligned}
        M_2(\mathcal{G})&= \sum_{uv\in E(G_{n_2})}3\times 3+\sum_{uv\in E(G_{n_3})}3\times 3+\sum_{{\substack{u\in V(G_{n_1}), \\ v\in V(G_{n_2})}}}2\times 3\\
        &\; \; +\sum_{{\substack{u\in I(G_{n_1}), \\ v\in V(G_{n_3})}}}2\times 3+\sum_{{\substack{uv\in E(\mathcal{G}),\\u\in V(G_{n_1}), v\in I(G_{n_1})}}}2\times 2
        +\sum_{{\substack{uv\in E(\mathcal{G}),\\u,v\in V(G_{n_1})}}}2\times 2\\
        &= 4m_1+9m_2+9m_3+2n_{1}^{2}-2n_1+6n_1n_2+6m_1n_3.
        \end{aligned}
    \end{equation*}
     Similarly when $G_{n_1}$ is not a triangle-free graph we get,\\
    $$M_2(\mathcal{G})= 9\left(m_1+m_2+m_3+n_1n_2+m_1n_3+\frac{n_1^2-n_1}{2}\right).$$
\end{itemize}

For $i= 1,2,3$, let $G_{n_i}$ be a graph of order $n_i$ and size $m_i$, then
 \begin{itemize}
     \item [(i)] $GA_{4}(\mathcal{G})=\begin{cases} m_1+m_2+m_3+\frac{2\sqrt{6}}{5}(n_1n_2+m_1n_3)+\frac{n_1^2-n_1}{2}, & \text{if $G_{n_1}$ is triangle-free}\\m_1+m_2+m_3+n_1n_2+m_1n_3+\frac{n_1^2-n_1}{2}, &\text{otherwise}\end{cases}.$
     \item[(ii)]$ABC_{5}(\mathcal{G})= \begin{cases}\frac{2}{3}(m_2+m_3)+\frac{1}{\sqrt{2}}\left(n_1n_2+m_1n_3+m_1+\frac{n_1(n_1-1)}{2}\right) , & \text{if $G_{n_1}$ is triangle-free}\\\frac{2}{3}(m_1+m_2+m_3+n_1n_2+m_1n_3)+\frac{n_1(n_1-1)}{3}, &\text{otherwise}\end{cases}.$
 \end{itemize}

\begin{itemize}
    \item [(i)]Let $\mathcal{G}= G_{n_1}^{C}\vee(G_{n_2}^V\cup G_{n_2}^E)$, where $G_{n_1}$ is triangle-free, then from (6) by using (10) we have\\
    \begin{equation*}
        \begin{aligned}
        GA_{4}(\mathcal{G})&= \sum_{uv\in E(G_{n_2})}2\frac{\sqrt{3\times 3}}{3+3}+\sum_{uv\in E(G_{n_3})}2\frac{\sqrt{3\times 3}}{3+3}+\sum_{{\substack{u\in V(G_{n_1}),\\ v\in V(G_{n_2})}}}2\frac{\sqrt{2\times 3}}{2+3}\\& +\sum_{{\substack{u\in I(G_{n_1}),\\ v\in V(G_{n_3})}}}2\frac{\sqrt{2\times 3}}{2+3}+\sum_{{\substack{u\in V(G_{n_1}),\\ v\in I(G_{n_1}),\\ uv\in E(\mathcal{G})}}}2\frac{\sqrt{2\times 2}}{2+2}+\sum_{{\substack{uv\in E(\mathcal{G}),\\  u,v\in V(G_{n_1})}}}2\frac{\sqrt{2\times 2}}{2+2}\\
        &= m_1+m_2+m_3+\frac{2\sqrt{6}}{5}(n_1n_2+m_1n_3)+\frac{n_1^2-n_1}{2}.
        \end{aligned}
    \end{equation*}
    Similarly when $G_{n_1}$ is not a triangle-free graph we get,\\
    $$GA_{4}(\mathcal{G})= m_1+m_2+m_3+n_1n_2+m_1n_3+\frac{n_1^2-n_1}{2}.$$
    \item[(ii)] Let $G_{n_1}$ be a triangle-free graph. Then from (7) by using (10) we get\\
    \begin{equation*}
       \scriptsize{ \begin{aligned}
        ABC_{5}(\mathcal{G})&= \sum_{uv\in E(G_{n_2})}\sqrt{\frac{3+3-2}{3\times 3}}+\sum_{uv\in E(G_{n_3})}\sqrt{\frac{3+3-2}{3\times 3}}+\sum_{{\substack{u\in V(G_{n_1}),\\  v\in V(G_{n_2})}}}\sqrt{\frac{2+3-2}{2\times 3}}\\& +\sum_{{\substack{u\in I(G_{n_1}),\\   v\in V(G_{n_3})}}}\sqrt{\frac{2+3-2}{2\times 3}}+\sum_{{\substack{uv\in E(\mathcal{G}),\\u\in V(G_{n_1}),\\ v\in I(G_{n_1})}}}\sqrt{\frac{2+2-2}{2\times 2}}+\sum_{{\substack{uv\in E(\mathcal{G}) \\ u,v\in V(G_{n_1})}}}\sqrt{\frac{2+2-2}{2\times 2}}\\
        &= \frac{2}{3}(m_2+m_3)+\frac{1}{\sqrt{2}}\left(n_1n_2+m_1n_3+m_1+\frac{n_1(n_1-1)}{2}\right).
        \end{aligned}}
    \end{equation*}
     Similarly when $G_{n_1}$ is not a triangle-free graph we get,\\
    $$ABC_{5}(\mathcal{G})= \frac{2}{3}(m_1+m_2+m_3+n_1n_2+m_1n_3)+\frac{n_1(n_1-1)}{3}.$$
\end{itemize}
